def increasingSubsequencesK(nums: list[int], k: int) -> list[list[int]]:
    res = []
    def backtrack(idx, path):
        if len(path) == k:
            res.append(list(path))
            return
        for i in range(idx, len(nums)):
            if not path or nums[i] > path[-1]:
                backtrack(i + 1, path + [nums[i]])
    backtrack(0, [])
    return res

